import { loadEnv, botToken, DISCORD_API } from './src/config.mjs';
import { makeFetchJson } from './src/discordApi.mjs';

const CHANNEL = '1533603278816936168';
const MSG = '1533624576578158731';

const env = await loadEnv();
const tok = botToken(env);
if (!tok) throw new Error('no AVA_DISCORD_BOT_TOKEN');
const fetchJson = makeFetchJson(tok);

const target = await fetchJson('/channels/' + CHANNEL + '/messages/' + MSG);
const around = await fetchJson('/channels/' + CHANNEL + '/messages?around=' + MSG + '&limit=15');

function brief(m) {
  return {
    id: m.id,
    author: m.author?.username + ' (' + m.author?.id + ')',
    bot: !!m.author?.bot,
    content: (m.content || '').slice(0, 800),
    ts: m.timestamp,
    refs: m.message_reference?.message_id || null,
    reactions: (m.reactions || []).map(r => (r.emoji?.name || '?') + ':' + r.count),
  };
}

console.log(JSON.stringify({
  target: brief(target),
  around: (around || []).map(brief).reverse(),
}, null, 2));

// Soft-ack
for (const emoji of ['⏱️', '👀']) {
  const enc = encodeURIComponent(emoji);
  try {
    await fetchJson('/channels/' + CHANNEL + '/messages/' + MSG + '/reactions/' + enc + '/@me', { method: 'PUT' });
    console.log('reacted', emoji);
  } catch (e) {
    console.error('react fail', emoji, e.message);
  }
}
"

